const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='motion-atlas-v1';let state={entries:{},favorites:[],custom:[]};try{state={...state,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{}
let catalog, leaves=[],category='',branch='',mode='cards',saved=false,selected=null;
const labels={planned:'Planned',reference:'Reference collected',building:'Building',ready:'Ready to reuse'};
const icons=['◉','◎','◇','◈','♫','≋','Aa','✳','↗','▱','⌘','⌁','◐','▨'];
const descriptions=['UI interactions, kinetic type, living objects, and data in motion.','Every projection, border, route, and camera move for your next story.','Illustrations, cutouts, textures, icons, and interface building blocks.','Devices, materials, lighting rigs, and dimensional scenes.','Small details you can hear. Clicks, sweeps, impacts, and atmosphere.','Find the feeling. Beds, beats, stems, and musical moments.','Build a visual voice with type families and typography systems.','Connect every scene with intention. Reveals, cuts, and finishing effects.','A vocabulary of visual approaches, creators, and motion techniques.','Reusable sequences for stories, launches, explainers, and social videos.','The foundations: camera, lighting, motion, and delivery.','Keep reusable components and rendering techniques within reach.','Shape the mood with series-inspired grades, filter families, LUTs, and color controls.','Paper, film, natural surfaces, digital patterns, and animated texture layers.'];
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notify('Storage is full. Export your progress now.');return false}}
function flatten(n,path=[]){const p=[...path,n.name];if(n.children){n.children.forEach(x=>flatten(x,p))}else leaves.push({...n,path:p,category:p[0]})}
function rebuild(){leaves=[];catalog.categories.forEach(x=>flatten(x));state.custom.forEach(x=>leaves.push(x))}
function merged(e){return {...e,...state.entries[e.id]}}
function matches(e){const v=merged(e),q=$('#search').value.toLowerCase().trim();return (!category||e.category===category)&&(!branch||e.id.startsWith(branch+'/'))&&(!saved||state.favorites.includes(e.id))&&(!$('#status').value||v.status===$('#status').value)&&(!q||[...e.path,v.notes,...(v.tags||[])].join(' ').toLowerCase().includes(q))}
function badge(status){return el('span','badge '+status,labels[status]||'Planned')}
function stats(){const a=leaves.map(merged),ref=a.filter(x=>x.references?.length).length,ready=a.filter(x=>x.status==='ready').length;$('#stat-total').textContent=leaves.length.toLocaleString();$('#all-count').textContent=leaves.length;$('#stat-categories').textContent=catalog.categories.length;$('#stat-ref').textContent=ref;$('#stat-ready').textContent=ready;$('#progress').style.width=(100*ready/a.length)+'%';$('#progress-caption').textContent=ready?`${ready} of ${a.length} entries ready to reuse.`:'Every great library starts with one reference.'}
function nav(){const box=$('#categories');box.replaceChildren();catalog.categories.forEach((c,i)=>{const b=el('button','nav'+(category===c.name?' active':''));b.append(el('span','nav-icon',icons[i]),el('span','',c.name),el('b','',leaves.filter(x=>x.category===c.name).length));b.onclick=()=>choose(c.name);box.append(b)});$('.all').classList.toggle('active',!category);}
function choose(name){category=name;branch='';$('#search').value='';nav();render()}
function collect(n){return leaves.filter(x=>x.id.startsWith(n.id+'/'))}
function cards(nodes){const wrap=el('div','cards');nodes.forEach((n,i)=>{const entries=collect(n).filter(matches);if(!entries.length)return;const b=el('button','collection-card'),art=el('div','card-art');art.style.setProperty('--tone',['#d5f99a','#afc5f4','#e6b99d','#c4b0eb'][i%4]);art.append(el('span','card-index',String(i+1).padStart(2,'0')),el('span','glyph',icons[i%icons.length]),el('span','card-corner','↗'));const body=el('div','card-body');body.append(el('h3','',n.name),el('p','',category?`${n.children.map(x=>x.name).slice(0,4).join(' · ')}`:descriptions[i]||'Grow your collection of reusable motion design.'));const meta=el('div','card-meta');meta.append(el('span','',entries.length+' entries'),el('span','',entries.filter(x=>merged(x).status==='ready').length+' ready'));body.append(meta);b.append(art,body);b.onclick=()=>{if(!category)category=n.name;else branch=n.id;nav();render()};wrap.append(b)});return wrap}
function entryCards(entries){const wrap=el('div','entry-grid');entries.forEach(e=>{const b=el('button','entry-card');b.append(badge(merged(e).status),el('strong','',(state.favorites.includes(e.id)?'★ ':'')+e.name),el('small','',e.path.slice(1,-1).join(' / ')));b.onclick=()=>openEntry(e);wrap.append(b)});return wrap}
function tree(entries){const root={};entries.forEach(e=>{let dest=root;e.path.slice(0,-1).forEach(p=>dest=dest[p]||(dest[p]={}));(dest._entries||(dest._entries=[])).push(e)});const wrap=el('div','tree-root');function build(obj,parent,depth){Object.entries(obj).forEach(([name,v])=>{if(name==='_entries'){v.forEach(e=>{const b=el('button','tree-leaf');b.append(el('span','',(state.favorites.includes(e.id)?'★ ':'')+e.name),badge(merged(e).status));b.onclick=()=>openEntry(e);parent.append(b)});return}const d=el('details'),s=el('summary','',name);let count=0;function tally(x){Object.entries(x).forEach(([k,v])=>k==='_entries'?count+=v.length:tally(v))}tally(v);s.append(el('small','',count));d.open=!!$('#search').value||!!category&&depth<2;d.append(s);build(v,d,depth+1);parent.append(d)})}build(root,wrap,0);return wrap}
function render(){stats();const entries=leaves.filter(matches);$('#result-count').textContent=entries.length.toLocaleString()+' entries'+(category?' in '+category:' across your atlas');$('#section-heading').textContent=branch?branch.split('/').at(-1).split('-').map(x=>x[0].toUpperCase()+x.slice(1)).join(' '):saved?'Saved for later':category||'Explore the collection';$('#section-subtitle').textContent=category?'Open a family, then collect the individual references.':'Go broad. Get specific. Find what’s next.';const content=$('#content');content.replaceChildren();if(category||branch){const b=el('button','back','← '+(branch?'Back to '+category:'All collections'));b.onclick=()=>{if(branch)branch='';else category='';nav();render()};content.append(b)}if(!entries.length){const empty=el('div','empty');empty.append(el('strong','','No entries found'),el('span','','Try another search or clear your filters.'));content.append(empty);return}let view;if(mode==='tree')view=tree(entries);else if(saved||$('#search').value||$('#status').value||branch)view=entryCards(entries);else view=cards(category?catalog.categories.find(x=>x.name===category).children:catalog.categories);content.append(view);if(mode==='cards'&&category&&!saved&&!branch&&!$('#search').value&&!$('#status').value){const extras=entries.filter(e=>e.custom);if(extras.length)content.append(entryCards(extras))}}
function openEntry(e){selected=e;const v=merged(e);$('#entry-title').textContent=e.name;$('#entry-path').textContent=e.path.slice(0,-1).join(' / ');$('#entry-status').value=v.status;$('#entry-priority').value=v.priority||'normal';$('#entry-refs').value=(v.references||[]).map(x=>typeof x==='string'?x:x.url).join('\n');$('#entry-preview').value=v.preview||'';$('#entry-code').value=v.code||'';$('#entry-license').value=v.license||'';$('#entry-notes').value=v.notes||'';$('#bookmark').textContent=state.favorites.includes(e.id)?'★ Saved for later':'☆ Save for later';const links=$('#entry-links');links.replaceChildren();[['Open preview',v.preview],['Open code',v.code]].forEach(([name,url])=>{const safe=safeURL(url);if(safe){const a=el('a','',name+' ↗');a.href=safe;a.target='_blank';a.rel='noopener';links.append(a)}});$('#detail').showModal()}
$('#entry-form').onsubmit=e=>{e.preventDefault();const references=$('#entry-refs').value.split('\n').map(x=>x.trim()).filter(Boolean);if(references.some(x=>!safeURL(x))){notify('Reference links must be valid HTTP or HTTPS URLs.');return}state.entries[selected.id]={status:$('#entry-status').value,priority:$('#entry-priority').value,references,preview:$('#entry-preview').value.trim()||null,code:$('#entry-code').value.trim()||null,license:$('#entry-license').value.trim()||null,notes:$('#entry-notes').value.trim(),updatedAt:new Date().toISOString()};persist();$('#detail').close();render();notify('Entry saved in this browser. Export to back it up.')};
$('#bookmark').onclick=()=>{const id=selected.id;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();$('#bookmark').textContent=state.favorites.includes(id)?'★ Saved for later':'☆ Save for later';render()};$('#close').onclick=()=>$('#detail').close();
$('#search').oninput=()=>render();$('#status').onchange=()=>render();$('#favorites').onclick=()=>{saved=!saved;$('#favorites').classList.toggle('saved-active',saved);$('#favorites').setAttribute('aria-pressed',saved);render()};$('#grid').onclick=()=>{mode='cards';$('#grid').classList.add('selected');$('#tree').classList.remove('selected');render()};$('#tree').onclick=()=>{mode='tree';$('#tree').classList.add('selected');$('#grid').classList.remove('selected');render()};$('.all').onclick=()=>choose('');
$('#export').onclick=()=>{const data={format:'motion-atlas-progress',version:1,exportedAt:new Date().toISOString(),...state};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=el('a');a.href=u;a.download='motion-atlas-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);notify('Progress exported. Keep it or send it to this chat.')};$('#import').onclick=()=>$('#file').click();
$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('File is too large.');const data=JSON.parse(await file.text());if(data.format!=='motion-atlas-progress'||data.version!==1||!data.entries||!Array.isArray(data.favorites)||!Array.isArray(data.custom))throw Error('Choose a Motion Atlas progress export.');const known=new Set(leaves.map(x=>x.id));for(const c of data.custom){if(typeof c.id!=='string'||typeof c.name!=='string'||!Array.isArray(c.path)||c.path.length<4||!catalog.categories.some(x=>x.name===c.category))throw Error('Invalid custom entry.');known.add(c.id)}for(const [id,v]of Object.entries(data.entries)){if(!known.has(id)||!v||!Object.hasOwn(labels,v.status)||v.references&&!Array.isArray(v.references))throw Error('Invalid entry data.')}state.entries={...state.entries,...data.entries};state.favorites=[...new Set([...state.favorites,...data.favorites.filter(x=>known.has(x))])];state.custom=[...new Map([...state.custom,...data.custom].map(x=>[x.id,x])).values()];persist();rebuild();nav();render();notify('Progress merged successfully.')}catch(err){notify(err.message||'Could not import that file.')}finally{e.target.value=''}};
$('#add').onclick=()=>{$('#new-category').value=category||catalog.categories[0].name;$('#new-dialog').showModal()};$('#new-cancel').onclick=()=>$('#new-dialog').close();$('#new-form').onsubmit=e=>{e.preventDefault();const name=$('#new-name').value.trim(),c=$('#new-category').value,section=$('#new-section').value.trim(),family=$('#new-family').value.trim();if(!name||!section||!family)return;const entry={id:'custom/'+crypto.randomUUID(),name,category:c,path:[c,section,family,name],status:'planned',priority:'normal',references:[],notes:'',custom:true};state.custom.push(entry);persist();rebuild();$('#new-dialog').close();$('#new-name').value='';choose(c);mode='tree';$('#tree').click();notify('New entry added to your collection.')};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('dialog[open]')){e.preventDefault();$('#search').focus()}});
try{const response=await fetch('catalog.json');if(!response.ok)throw Error('The catalog could not be loaded.');catalog=await response.json();rebuild();catalog.categories.forEach(c=>{const o=el('option','',c.name);o.value=c.name;$('#new-category').append(o)});nav();render()}catch(err){$('#error').hidden=false;$('#error').textContent=err.message+' Serve this folder with a local HTTP server instead of opening index.html directly.'}
